<?php
namespace qqworld_collector\module\static_cache; use qqworld_collector\lib; class remove extends lib { var $log_id = 'static-cache'; var $abspath; public function init() { if (!function_exists('WP_Filesystem')) include ABSPATH . DIRECTORY_SEPARATOR . 'wp-admin' . DIRECTORY_SEPARATOR . 'includes' .DIRECTORY_SEPARATOR . 'file.php'; WP_Filesystem(); if ($this->options->qc_static_cache_enabled) { add_action( 'before_delete_post', array($this, 'before_delete_post') ); add_action( 'pre_delete_term', array($this, 'pre_delete_term'), 10, 2 ); } } private function is_dir_empty($dir) { return count(scandir($dir)) <= 2; } private function remove_path($path) { if (!is_dir($path) || $this->is_dir_empty($path)) { if (is_dir($path)) rmdir( $path ); if (strlen(ABSPATH)-1 < strlen($path) ) $this->remove_path(dirname($path)); } } private function remove_file($url) { global $wp_filesystem; if ($url == '/') return; $path = dirname($url); $filename = urldecode(basename($url)); if (!preg_match('/\.html?$/i', $filename)) { $path .= $path == DIRECTORY_SEPARATOR ? $filename . DIRECTORY_SEPARATOR : DIRECTORY_SEPARATOR . $filename . DIRECTORY_SEPARATOR; $filepath = $this->abspath . $path; if (is_dir($filepath)) { $files = scandir($filepath); if (!empty($files)) foreach ($files as $file) { if ($file == '..' || $file == '.') continue; $file_path = $filepath . $file; if (is_dir($file_path) && strlen(ABSPATH)-1 < strlen($filepath) ) $wp_filesystem->rmdir( $file_path, true ); elseif (preg_match('/\.html$/', $file_path) && file_exists($file_path) && !unlink($file_path)) do_action( 'qqworld-collector-log', $this->log_id, 'Can not delete file, Path:', $file_path ); } } } else { if ($path != DIRECTORY_SEPARATOR) { $path .= DIRECTORY_SEPARATOR; } $filepath = $this->abspath . $path . $filename; if (preg_match('/\.html$/', $filepath) && file_exists($filepath) && !unlink($filepath)) do_action( 'qqworld-collector-log', $this->log_id, 'Can not delete file, Path:', $filepath ); } $this->remove_path($this->abspath.$path); } public function singular($post_id) { $post_status = get_post_status($post_id); switch ($this->options->qc_static_cache_mode) { case 'half': $url = get_permalink($post_id); $parser = parse_url($url); $uri = $parser['path']; $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri); if (file_exists($path)) unlink($path); $uri = preg_match('/\/$/i', $uri) ? $uri : $uri . '/'; $post = get_post( $post_id ); $post_content = $post->post_content; $pages = count(explode( '<!--nextpage-->', $post_content )); if ($pages > 1) { for ($page=2; $page<=$pages; $page++) { $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri . $page); if (file_exists($path)) if (!unlink($path)) do_action( 'qqworld-collector-log', $this->log_id, 'Can not delete file, Path:', $path ); } } break; case 'pure': $url = str_replace(home_url(), '', get_permalink($post_id)); $this->remove_file($url); break; } return true; } public function archive($term_id, $taxonomy) { $term_link = get_term_link(intval($term_id), $taxonomy); switch ($this->options->qc_static_cache_mode) { case 'half': $url = $term_link; $parser = parse_url($url); $uri = $parser['path']; $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri); if (file_exists($path)) if (!unlink($path)) do_action( 'qqworld-collector-log', $this->log_id, 'Can not delete file, Path:', $path ); if ($page == 'all') { $uri = preg_match('/\/$/i', $uri) ? $uri : $uri . '/'; if ($term->count) { $posts_per_page = get_option( 'posts_per_page' ); if ($term->count > $posts_per_page) { $pages = $term->count / $posts_per_page; $pages = is_int($pages) ? $pages : intval($pages) + 1; for ($page=2; $page<=$pages; $page++) { $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri . 'page/' . $page); if (file_exists($path)) if (!unlink($path)) do_action( 'qqworld-collector-log', $this->log_id, 'Can not delete file, Path:', $path ); } } } } break; case 'pure': $url = str_replace(home_url(), '', $term_link); $this->remove_file($url); break; } return true; } public function before_delete_post($postid) { $this->singular($postid); } public function pre_delete_term($term, $taxonomy) { $this->archive($term, $taxonomy); } } ?>